// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import {applyGraphPositions, createNodeMetadataSelector} from "../../../main/frontend/graph-explorer/graph-model.ts";

test("position-only frames reuse semantic metadata without hiding label or type changes", () => {
  const select = createNodeMetadataSelector();
  const nodes = [{id: "urn:n", kind: "iri", label: "Old", x: 1, y: 2}];
  assert.equal(select(nodes), nodes);
  for (let i = 0; i < 100; i++) assert.equal(select([{...nodes[0], x: i, y: i}]), nodes);
  for (const change of [{label: "New"}, {types: [{id: "urn:type", label: "Type"}]}, {pinned: true}, {language: "nb"}, {datatype: "urn:t"}]) {
    const changed = [{...nodes[0], ...change}];
    assert.equal(select(changed), changed);
    select(nodes);
  }
  assert.equal(select([]).length, 0);
});

test("direction changes invalidate literal metadata", () => {
  const select = createNodeMetadataSelector();
  const literal = [{ id: "literal", kind: "literal", label: "مرحبا", language: "ar" }];
  select(literal);
  const directed = [{ ...literal[0], direction: "rtl" }];
  assert.equal(select(directed), directed);
});

test("late layout positions preserve current label/type hydration and edge metadata", () => {
  const graph = {revision: 4, nodes: [{id: "urn:n", kind: "iri", label: "Hydrated", types: [{id: "urn:type", label: "Type"}]}], edges: []};
  const result = applyGraphPositions(graph, new Map([["urn:n", {x: 12, y: 34}]]));
  assert.equal(result.nodes[0].label, "Hydrated");
  assert.equal(result.nodes[0].types, graph.nodes[0].types);
  assert.equal(result.edges, graph.edges);
  assert.equal(graph.nodes[0].x, undefined);
  assert.equal(result.nodes[0].x, 12);
});
